package com.emie.designpm.service;
import com.emie.designpm.controller.AuthController;import com.emie.designpm.entity.*;import com.emie.designpm.repository.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class PointProgramOperationsServiceTest{
 @Test void proposalIsIndependentAndRequiresDesignImage(){PointTaskProposalRepository proposals=mock(PointTaskProposalRepository.class);PointProgramOperationsService service=new PointProgramOperationsService(proposals,mock(PointTaskForecastRepository.class),mock(ProjectRepository.class),mock(ProjectService.class));assertThrows(IllegalArgumentException.class,()->service.submitProposal("原创产品","自主开发","[]","2026-09-30",session("d1","designer")));when(proposals.save(any())).thenAnswer(i->i.getArgument(0));PointTaskProposal saved=service.submitProposal("原创产品","自主开发","[{\"storedName\":\"design.png\"}]","2026-09-30",session("d1","designer"));assertNull(saved.getProjectId());assertNull(saved.getPointRuleCode());assertNull(saved.getDifficultyCode());assertEquals("[{\"storedName\":\"design.png\"}]",saved.getReferenceImagesJson());}
 @Test void approvingProposalCreatesNewProjectAndUnscoredOfficialTask(){PointTaskProposalRepository proposals=mock(PointTaskProposalRepository.class);PointTaskForecastRepository forecasts=mock(PointTaskForecastRepository.class);ProjectRepository projects=mock(ProjectRepository.class);ProjectService projectService=mock(ProjectService.class);PointProgramOperationsService service=new PointProgramOperationsService(proposals,forecasts,projects,projectService);PointTaskProposal proposal=new PointTaskProposal();proposal.setId(1L);proposal.setApplicantUserId("d1");proposal.setApplicantName("设计师");proposal.setTitle("原创产品");proposal.setDescription("自主开发");proposal.setReferenceImagesJson("[{\"storedName\":\"design.png\"}]");proposal.setPlannedDate("2026-09-30");proposal.setStatus("SUBMITTED");when(proposals.findById(1L)).thenReturn(Optional.of(proposal));when(proposals.save(any())).thenAnswer(i->i.getArgument(0));Project created=new Project();created.setId(9L);when(projectService.createProject(anyMap())).thenReturn(created);Project project=new Project();SubTask task=new SubTask();task.setId(88L);project.setTasks(new ArrayList<>(List.of(task)));when(projectService.addSubTask(eq(9L),anyMap())).thenReturn(project);PointTaskProposal result=service.reviewProposal(1L,true,"同意立项",session("a1","admin"));assertEquals("APPROVED",result.getStatus());assertEquals(9L,result.getProjectId());assertEquals(88L,result.getCreatedTaskId());verify(projectService).createProject(argThat(body->"原创产品".equals(body.get("productName"))&&proposal.getReferenceImagesJson().equals(body.get("referenceImagesJson"))));verify(projectService).addSubTask(eq(9L),argThat(body->Boolean.TRUE.equals(body.get("selfInitiated"))&&!body.containsKey("pointRuleCode")&&!body.containsKey("difficultyCode")&&"d1".equals(body.get("designerId"))&&proposal.getReferenceImagesJson().equals(body.get("referenceImagesJson"))));}
 @Test void publishedForecastIsVisibleToDesigner(){PointTaskProposalRepository proposals=mock(PointTaskProposalRepository.class);PointTaskForecastRepository forecasts=mock(PointTaskForecastRepository.class);PointTaskForecast item=new PointTaskForecast();item.setStatus("PUBLISHED");when(forecasts.findByStatusOrderByMonthKeyAscCreatedAtAsc("PUBLISHED")).thenReturn(List.of(item));PointProgramOperationsService service=new PointProgramOperationsService(proposals,forecasts,mock(ProjectRepository.class),mock(ProjectService.class));assertEquals(1,service.forecasts(session("d1","designer")).size());}
 private AuthController.AuthSession session(String id,String role){return new AuthController.AuthSession(id,role,id);}
}
